"""Goal plans: interview, six built-in plans, gear/joint/minute fitting, keep-my-program, meals hand-off, season phases (Nov 2)."""
import asyncio, subprocess, sys, time
from playwright.async_api import async_playwright
PORT = 8792
srv = subprocess.Popen([sys.executable, '-m', 'http.server', str(PORT), '-d', 'dist'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL); time.sleep(1)
URL = f'http://localhost:{PORT}/'; results = []
def check(name, ok, detail=''):
    results.append(bool(ok)); print(('PASS ' if ok else 'FAIL ') + name + (' - ' + str(detail) if detail else ''))
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); pg = await (await b.new_context(viewport={'width': 390, 'height': 844})).new_page(); errs = []
        await pg.add_init_script("try { localStorage.setItem('liftbook.tourDone', '1') } catch (e) {}")
        pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.goto(URL); await pg.wait_for_timeout(1500); ev = pg.evaluate
        check('six goal plans on the Programs shelf', await ev("['gp-recomp3','gp-recomp4','gp-bulk4','gp-cut3','gp-strength3','gp-hybrid'].every(id => getRoutine(id) && getRoutine(id).days.length)"))
        A = "({ goal: 'recomp', sport: 'box', keep: false, days: 3, mins: 60, gear: 'gym', cardio: ['road'], joints: [], season: { on: false } })"
        plan = lambda extra: ev(f"(() => {{ const r = buildGoalPlan(Object.assign({A}, {extra})); return {{ name: r.name, days: r.days.map(d => ({{ n: d.name, ex: d.items.map(i => exName(i.ex)), sets: d.items.map(i => i.sets) }})), note: r.note }}; }})()")
        r = await plan('{}'); check('recomp, 3 days → Recomp 3-Day', r['name'] == 'My Recomp 3-Day' and len(r['days']) == 3, r['name'])
        r = await plan("{ days: 4 }"); check('recomp, 4 days → upper/lower', r['name'] == 'My Recomp Upper/Lower 4-Day')
        r = await plan("{ goal: 'strength' }"); check('strength → Strength 3-Day', r['name'] == 'My Strength 3-Day')
        r = await plan("{ goal: 'mass', days: 4 }"); check('size, 4 days → Lean Bulk 4-Day', r['name'] == 'My Lean Bulk 4-Day')
        r = await plan("{ goal: 'lose', days: 4 }"); check('fat loss → Cut 3-Day plus a steady cardio day on the 4th day', r['name'] == 'My Cut 3-Day' and len(r['days']) == 4 and 'Conditioning' in r['days'][3]['n'], [d['n'] for d in r['days']])
        r = await plan("{ goal: 'speed', days: 5, cardio: ['row'] }")
        check('speed, 5 days, rower → Hybrid with rowing intervals', r['name'] == 'My Hybrid Athlete 3+2' and any('rowing' in d['n'] and 'Rowing Machine (Erg)' in d['ex'] for d in r['days']), [d['n'] for d in r['days']])
        r = await plan("{ goal: 'sport', sport: 'swim', days: 5, cardio: ['pool'] }"); check('swimmer with a pool → swim conditioning', any('Swim' in d['ex'] for d in r['days']))
        r = await plan("{ goal: 'sport', sport: 'box', days: 5, cardio: ['bag'] }"); check('boxer with a bag → bag work', any('Heavy Bag Rounds' in d['ex'] for d in r['days']))
        r = await plan("{ gear: 'db' }"); allex = sum([d['ex'] for d in r['days']], [])
        check('dumbbells only → no barbell lifts', 'Back Squat' not in allex and 'Bench Press' not in allex and 'Goblet Squat' in allex, allex[:8])
        r = await plan("{ gear: 'bw' }"); allex = sum([d['ex'] for d in r['days']], [])
        check('bodyweight only → push-ups, air squats', 'Push-Ups' in allex and 'Air Squat' in allex and 'Deadlift' not in allex)
        r = await plan("{ joints: ['knees', 'back'] }"); allex = sum([d['ex'] for d in r['days']], [])
        check('easy on knees and back → swaps, explained', 'Back Squat' not in allex and 'Deadlift' not in allex and 'Bulgarian Split Squat' not in allex and 'Joint care' in r['note'], r['note'][-140:])
        r = await plan("{ mins: 30 }"); check('30 minutes → 4 exercises a day', all(len(d['ex']) <= 4 for d in r['days']))
        base = await plan("{ days: 4 }"); bulk = await plan("{ days: 4, season: { on: true, bulkFrom: '2000-01-01', cutFrom: '2999-01-01', cutTo: '2999-06-01' } }")
        check('winter bulk → Lean Bulk with more accessory sets', bulk['name'] == 'My Lean Bulk 4-Day' and sum(bulk['days'][0]['sets']) > 8, bulk['days'][0]['sets'])
        cut = await plan("{ days: 4, season: { on: true, bulkFrom: '2000-01-01', cutFrom: '2000-02-01', cutTo: '2999-06-01' } }"); check('in the cut window → Cut plan', cut['name'] == 'My Cut 3-Day')
        # the interview, start to finish
        await ev("(() => { S.sessions = {}; S.meta.settings.program = 'self'; S.meta.settings.addons = []; delete S.meta.settings.plan; S.ver++; touch(); UI.setTab('train'); })()"); await pg.wait_for_timeout(200)
        await ev("openSheet({ type: 'program' })"); await pg.wait_for_timeout(150)
        check('Choose a program offers Build my plan', await pg.locator('#pick-goal').count() == 1)
        await pg.click('#pick-goal'); await pg.wait_for_timeout(200)
        await pg.click('#gs-goal-speed'); await pg.click('#gs-next'); await pg.wait_for_timeout(100)
        check('no program yet → no keep question', await pg.locator('#gs-keep').count() == 0)
        await pg.click('#gs-days-5'); await pg.click('#gs-mins-45'); await pg.click('#gs-next'); await pg.wait_for_timeout(100)
        await pg.click('#gs-cardio-road'); await pg.click('#gs-cardio-airbike'); await pg.click('#gs-joints-knees'); await pg.click('#gs-next'); await pg.wait_for_timeout(150)
        nm = await pg.locator('#gs-name').text_content(); dtxt = await pg.locator('#gs-days').text_content()
        check('summary shows the fitted plan', nm == 'My Hybrid Athlete 3+2' and 'assault bike' in dtxt and 'Broad Jump' not in dtxt, dtxt[:200])
        await pg.click('#gs-go'); await pg.wait_for_timeout(300)
        check('Use this plan → following your copy', await ev("programId() === 'gp-mine' && S.meta.routines['gp-mine'].days.length === 5 && S.meta.settings.plan.goal === 'speed'"))
        # keep my program
        await ev("(() => { S.meta.settings.program = 'bi-newt-4day'; S.meta.settings.addons = []; delete S.meta.settings.plan; S.ver++; touch(); })()")
        await ev("openSheet({ type: 'goalSetup' })"); await pg.wait_for_timeout(150)
        await pg.click('#gs-goal-sport'); await pg.click('#gs-sport-box'); await pg.click('#gs-next'); await pg.wait_for_timeout(100)
        check('has a program → keep it is the default', await pg.locator('#gs-keep.on').count() == 1)
        await pg.click('#gs-days-6'); await pg.click('#gs-next'); await pg.click('#gs-next'); await pg.wait_for_timeout(150)
        res = await pg.locator('#gs-result').text_content()
        check('keep → fight conditioning on the free days', 'Fight Rounds' in res and '2 free days' in res, res[:200])
        await pg.click('#gs-go'); await pg.wait_for_timeout(300)
        check('program kept, add-on added', await ev("programId() === 'bi-newt-4day' && S.meta.settings.addons.includes('bi-cond-fight')"))
        await ev("closeSheet()"); await pg.wait_for_timeout(100)
        # meals hand-off with a bulk
        await ev("(() => { S.meta.settings.program = 'self'; S.ver++; touch(); })()")
        await ev("openSheet({ type: 'goalSetup' })"); await pg.wait_for_timeout(150)
        await pg.click('#gs-goal-mass'); await pg.click('#gs-season'); await pg.wait_for_timeout(80)
        check('season dates default to mid-Feb and late May', (await pg.locator('#gs-cutFrom').input_value()).endswith('-02-15') and (await pg.locator('#gs-cutTo').input_value()).endswith('-05-25'))
        for _ in range(3): await pg.click('#gs-next'); await pg.wait_for_timeout(60)
        await pg.click('#gs-meals'); await pg.wait_for_timeout(300)
        check('then the meal setup opens with a slow gain filled in', await pg.locator('#tg-from-goal').count() == 1 and await pg.locator('#tg-goal-gain.on').count() == 1 and await pg.locator('#tg-pace-gentle.on').count() == 1)
        await ev("closeSheet()"); await pg.wait_for_timeout(100)
        await ev("openSheet({ type: 'mealTargets' })"); await pg.wait_for_timeout(150)
        check('meal setup offers the training questions too', await pg.locator('#tg-goal').count() == 1)
        await ev("closeSheet()"); await pg.wait_for_timeout(100)
        # season switch, asked first
        await ev("mealCommit(m => { m.me = { h: 180, w: 80, age: 30, sex: 'm', act: 2, goal: 'gain', pace: 'gentle', us: true }; m.goals = { kcal: 3000, p: 160 }; })")
        await ev("commit(st => { const g = st.meta.settings.plan; g.season = { ...g.season, on: true, bulkFrom: '2000-01-01', cutFrom: ymd(addDays(new Date(), -1)), cutTo: '2999-05-25', cur: 'bulk', asked: {} }; }, 'meta'); UI.setTab('train')"); await pg.wait_for_timeout(250)
        check('cut date passed → Train asks before switching', await pg.locator('#phase-check').count() == 1 and await ev("S.meta.settings.plan.season.cur") == 'bulk')
        await pg.click('#ph-later'); await pg.wait_for_timeout(200)
        check('In a week hides it', await pg.locator('#phase-check').count() == 0)
        await ev("commit(st => { st.meta.settings.plan.season.asked = {}; }, 'meta')"); await pg.wait_for_timeout(200)
        kcal0 = await ev("ML().goals.kcal")
        await pg.click('#ph-switch'); await pg.wait_for_timeout(300)
        st = await ev("({ cur: S.meta.settings.plan.season.cur, goal: ML().me.goal, kcal: ML().goals.kcal, prog: programId(), name: (getRoutine(programId()) || {}).name })")
        check('Switch now → cut calories and the cut plan', st['cur'] == 'cut' and st['goal'] == 'lose' and st['kcal'] < kcal0 and st['name'] == 'My Cut 3-Day', st)
        # Build my plan fixes (Nov 2 evening)
        for d, want in ((2, 2), (6, 6), (7, 7)):
            r = await plan(f"{{ days: {d} }}"); check(f'{d} days a week → {want} days in the plan', len(r['days']) == want, [x['n'] for x in r['days']])
        r = await plan("{ goal: 'speed', days: 4 }"); check('get faster at 4 days → 4 days with an interval day', len(r['days']) == 4 and any('intervals' in x['n'] for x in r['days']), [x['n'] for x in r['days']])
        r = await plan("{ goal: 'sport', sport: 'run', days: 3 }"); check('a sport at 3 days still gets conditioning', any('Conditioning' in x['n'] for x in r['days']), [x['n'] for x in r['days']])
        r = await plan("{ gear: 'bw' }"); allex = sum([d['ex'] for d in r['days']], [])
        check('bodyweight only → no pull-ups, dips or hanging', not any(x in allex for x in ('Pull-Up', 'Dips', 'Hanging Leg Raises')) and 'Inverted Row' in allex, allex)
        r = await plan("{ gear: 'bar' }"); allex = sum([d['ex'] for d in r['days']], []); check('with a pull-up bar → pull-ups', 'Pull-Up' in allex)
        r = await plan("{ gear: 'bw', joints: ['shoulders', 'wrists'] }"); allex = sum([d['ex'] for d in r['days']], [])
        check('bodyweight with sore shoulders and wrists → no machines', not any('Machine' in x or 'Lat Pulldown' in x or 'Pushdown' in x for x in allex), allex)
        r = await plan("{ gear: 'db', joints: ['shoulders', 'wrists', 'knees'] }"); allex = sum([d['ex'] for d in r['days']], [])
        check('several sore joints → the main press is still a press', not any(x in allex for x in ('Scapular Push-Up',)) and 'Lateral Raises' != r['days'][1]['ex'][1], r['days'][1]['ex'])
        r = await plan("{ gear: 'db', joints: ['knees'] }"); allex = sum([d['ex'] for d in r['days']], [])
        check('the joint note only names lifts that are in the plan', all(t.split(' instead of ')[0] in allex for t in r['note'].split('Joint care: ')[1].rstrip('.').split(', ')) if 'Joint care' in r['note'] else True, r['note'])
        r = await plan("{ goal: 'strength', mins: 30 }"); check('30-minute strength days stay at 11 sets or fewer', all(sum(d['sets']) <= 11 for d in r['days']), [sum(d['sets']) for d in r['days']])
        r = await plan("{ goal: 'sport', sport: 'box', days: 5, cardio: ['road'] }"); allex = sum([d['ex'] for d in r['days']], [])
        check('boxer with no bag → shadowboxing, not bag rounds', 'Heavy Bag Rounds' not in allex and 'Shadowboxing Rounds' in allex and 'heavy bag' in r['note'], r['note'][-120:])
        r = await plan("{ goal: 'sport', sport: 'swim', days: 5, cardio: ['road'] }"); check('swimmer with no pool is told why', 'pool' in r['note'])
        r = await plan("{ goal: 'mass', days: 3 }"); check('get bigger at 3 days is named a bulk', r['name'] == 'My Lean Bulk 3-Day', r['name'])
        r = await plan("{ joints: ['knees'] }"); allex = sum([d['ex'] for d in r['days']], []); check('sore knees → box squat or no squat', 'Back Squat' not in allex)
        # Fix list (Nov 2 evening)
        check('answers live in settings.plan; the weekly goal stays a number', await ev("typeof S.meta.settings.goal === 'number' && typeof S.meta.settings.plan === 'object'"))
        check('old builds that saved answers over the goal are moved back', await ev("(() => { const m = normalizeMeta({ settings: { goal: { goal: 'mass', days: 5, season: { on: false } } } }); return m.settings.goal === 5 && m.settings.plan.goal === 'mass'; })()"))
        r = await plan("{ goal: 'strength', season: { on: true, bulkFrom: '2000-01-01', cutFrom: '2000-02-01', cutTo: '2999-06-01' } }")
        check('a season left on under a goal that hides the switch is ignored', r['name'] == 'My Strength 3-Day', r['name'])
        await ev("(() => { S.meta.settings.program = 'bi-newt-4day'; S.meta.settings.plan.keep = false; S.meta.settings.plan.goal = 'mass'; S.meta.settings.plan.season = { on: true, bulkFrom: '2000-01-01', cutFrom: '2000-02-01', cutTo: '2999-05-25', cur: 'bulk', asked: {} }; S.ver++; touch(); })()")
        await ev("switchPhase('cut')"); await pg.wait_for_timeout(200)
        check('season switch never replaces a program you picked', await ev("programId()") == 'bi-newt-4day')
        check('no page errors', not errs, errs[:3]); await b.close()
try: asyncio.run(main())
finally: srv.terminate()
print(f'{sum(results)}/{len(results)} passed'); sys.exit(0 if all(results) else 1)
